<template><div class="target-picker"><label v-if="!fixedScope" class="field"><span>目标空间</span><select class="input" v-model="scope" @change="goRoot"><option value="">我的文件</option><option v-for="s in spaces" :key="s.id" :value="s.id">{{s.name}}</option></select></label><nav class="breadcrumb"><button type="button" @click="goRoot">{{scopeName}}</button><template v-for="(c,i) in crumbs" :key="c.id"><Icon name="right"/><button type="button" @click="go(c.id,crumbs.slice(0,i+1))">{{c.name}}</button></template></nav><p class="error-text" v-if="error">{{error}} <button type="button" class="text-button" @click="load">重试</button></p><div class="target-folders"><p v-if="busy">加载中…</p><button v-for="item in folders" :key="item.id" type="button" class="target-folder" :disabled="exclude.includes(item.id)" @click="choose(item)"><FileGlyph :item="item"/><span>{{item.name}}</span><Icon name="right"/></button><p v-if="!busy&&!folders.length&&!error" class="muted">此目录没有子文件夹，可选择当前目录。</p></div><p class="form-note">已选：{{scopeName}} / {{crumbs.map(c=>c.name).join(' / ')||'根目录'}} {{modelValue?.name||''}}</p></div></template>
<script setup>
import { ref,onMounted,computed,onUnmounted } from 'vue';import * as api from '../api';import Icon from './Icon.vue';import FileGlyph from './FileGlyph.vue';
const props=defineProps({modelValue:Object,fixedScope:Object,files:Boolean,exclude:{type:Array,default:()=>[]}}),emit=defineEmits(['update:modelValue']);
const spaces=ref([]),scope=ref(props.fixedScope?.scopeType==='WORKSPACE'?props.fixedScope.scopeId:''),parent=ref(''),crumbs=ref([]),folders=ref([]),busy=ref(false),error=ref('');let seq=0,alive=true;
const scopeName=computed(()=>spaces.value.find(s=>s.id===scope.value)?.name||(scope.value?'协作空间':'我的文件'));
async function load(){const n=++seq;busy.value=true;error.value='';try{const list=scope.value?await api.getWorkspaceItems(scope.value,parent.value):await api.getMyDriveItems(parent.value);if(n===seq&&alive)folders.value=(list||[]).filter(i=>props.files||i.itemType==='folder');}catch(e){if(n===seq&&alive)error.value=e.message;}finally{if(n===seq&&alive)busy.value=false;}}
function choose(item){if(item.itemType==='folder')go(item.id,[...crumbs.value,{id:item.id,name:item.name}]);else emit('update:modelValue',{scopeType:scope.value?'WORKSPACE':'PERSONAL',scopeId:scope.value,parentId:parent.value,itemId:item.id,name:item.name});}
function go(id,list){parent.value=id;crumbs.value=list;emit('update:modelValue',{scopeType:scope.value?'WORKSPACE':'PERSONAL',scopeId:scope.value,parentId:id});void load();}
function goRoot(){go('',[]);}
onMounted(async()=>{try{spaces.value=(await api.getWorkspaces()).filter(s=>s.status==='ACTIVE'&&['OWNER','ADMIN','MEMBER'].includes(s.myRole));}catch(e){error.value=e.message;}goRoot();});onUnmounted(()=>{alive=false;seq++;});
</script>
